	@Test
	void namedPathEndpointsKeepGraphDomainSemanticsAcrossNullableAndNestedPaths() throws Exception {
		List<String> paths = List.of("<urn:edge>*", "<urn:edge>?", "^<urn:edge>*",
				"(<urn:edge>|<urn:other>)*", "(<urn:edge>?/<urn:other>?)", "((^<urn:edge>)?)*");
		for (boolean sparql : List.of(false, true)) {
			try (Harness harness = new Harness(sparql)) {
				for (String path : paths) {
					for (Value value : List.of(VF.createIRI("urn:absent"), VF.createIRI("urn:a"),
							VF.createIRI("urn:unrelated"), VF.createLiteral("first"), VF.createLiteral("absent"))) {
						harness.assertMatches("SELECT ?s ?o WHERE {?s " + path + " ?o}", Map.of("s", value));
						harness.assertMatches("SELECT ?s ?o WHERE {?s " + path + " ?o}", Map.of("o", value));
						harness.assertMatches("SELECT ?s ?o WHERE {?s " + path + " ?o}",
								Map.of("s", value, "o", value));
						harness.assertMatches("SELECT ?s WHERE {?s " + path + " ?s}", Map.of("s", value));
					}
					for (Value value : List.of(VF.createIRI("urn:absent"), VF.createLiteral("first"),
							VF.createLiteral("absent"))) {
						harness.assertMatches("SELECT ?s WHERE {VALUES ?s {<urn:a>} FILTER EXISTS {?x "
								+ path + " ?o}}", Map.of("x", value));
						harness.assertMatches("SELECT ?s WHERE {VALUES ?s {<urn:a>} FILTER EXISTS {?o "
								+ path + " ?x}}", Map.of("x", value));
					}
					harness.assertMatches("SELECT ?o WHERE {\"absent\" " + path + " ?o}", Map.of());
				}
			}
		}
	}

	@Test
	void repeatedBlankNodeLabelsKeepOneBasicGraphPatternThroughBothAdapters() {
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			try (Harness harness = new Harness(sparql)) {
				var p = VF.createIRI("urn:label-p");
				var q = VF.createIRI("urn:label-q");
				var link = VF.createIRI("urn:label-link");
				var shared = VF.createBNode("shared");
				var leftOnly = VF.createBNode("left-only");
				var rightOnly = VF.createBNode("right-only");
				var wrong = VF.createBNode("wrong-parameter");
				try (var connection = harness.data.getConnection()) {
					connection.add(shared, p, VF.createLiteral(1));
					connection.add(shared, q, VF.createLiteral("match"));
					connection.add(leftOnly, p, VF.createLiteral(1));
					connection.add(rightOnly, q, VF.createLiteral("nonmatching"));
					connection.add(wrong, p, VF.createLiteral(2));
					connection.add(wrong, q, VF.createLiteral("wrong"));
					connection.add(shared, link, VF.createIRI("urn:matched-bridge"));
					connection.add(VF.createIRI("urn:matched-bridge"), q, VF.createLiteral("path-match"));
					connection.add(rightOnly, link, VF.createIRI("urn:unmatched-bridge"));
					connection.add(VF.createIRI("urn:unmatched-bridge"), q, VF.createLiteral("path-nonmatching"));
					connection.add(wrong, link, VF.createIRI("urn:wrong-bridge"));
					connection.add(VF.createIRI("urn:wrong-bridge"), q, VF.createLiteral("path-wrong"));
				}
				MapBindingSet matched = new MapBindingSet();
				matched.addBinding("x", VF.createLiteral(1));
				matched.addBinding("o", VF.createLiteral("match"));
				MapBindingSet pathMatched = new MapBindingSet();
				pathMatched.addBinding("x", VF.createLiteral(1));
				pathMatched.addBinding("o", VF.createLiteral("path-match"));
				List<BasicGraphPatternCase> cases = List.of(
						new BasicGraphPatternCase("_:b <urn:label-p> ?x . _:b <urn:label-q> ?o", List.of(matched)),
						new BasicGraphPatternCase("_:b <urn:label-p> ?x . _:b <urn:label-q> \"nonmatching\"",
								List.of()),
						new BasicGraphPatternCase("_:b <urn:label-p> ?x . "
								+ "_:b (<urn:label-link>/(<urn:label-q>|<urn:missing>)) ?o", List.of(pathMatched)));
				assertAll(cases.stream().map(test -> () -> {
					String query = "SELECT ?x ?o WHERE {" + test.body() + "}";
					Map<String, Value> parameters = Map.of("x", VF.createLiteral(1));
					assertThat(Harness.evaluate(harness.data, query, parameters))
							.as("local shared-label query=%s", query)
							.containsExactlyInAnyOrderElementsOf(test.expected());
					assertThat(harness.service(query, parameters)).as("adapter=%s shared-label query=%s", sparql, query)
							.containsExactlyInAnyOrderElementsOf(test.expected());
				}));
			}
		}));
	}

	private record BasicGraphPatternCase(String body, List<BindingSet> expected) {
	}

	@Test
	void directPreparedServiceRetainsParameterIdentityForOneAndTwoRuntimeRows() {
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			try (Harness harness = new Harness(sparql)) {
				Value parameter = harness.service("SELECT ?node WHERE {<urn:a> <urn:node> ?node}", Map.of())
						.get(0)
						.getValue("node");
				assertThat(parameter).isInstanceOf(RemoteBNode.class);
				MapBindingSet parameters = new MapBindingSet();
				parameters.addBinding("x", parameter);
				TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
						"SELECT ?copy WHERE {SERVICE <urn:endpoint> {BIND(?x AS ?copy)}}", null).getTupleExpr();
				new BindingAssignerOptimizer().optimizeForPreparedQuery(expression, parameters);
				AtomicReference<Service> found = new AtomicReference<>();
				expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
					@Override
					public void meet(Service service) {
						found.set(service);
					}
				});
				Service logical = found.get();
				Service snapshot = logical.clone();
				String source = logical.getServiceExpressionString();
				assertAll(List.of(1, 2).stream().map(count -> () -> {
					List<BindingSet> inputs = Collections.nCopies(count, EmptyBindingSet.getInstance());
					List<BindingSet> actual = new ArrayList<>();
					try (var rows = harness.endpoint.evaluate(logical,
							new CloseableIteratorIteration<>(inputs.iterator()), null)) {
						while (rows.hasNext()) {
							actual.add(rows.next());
						}
					}
					assertThat(logical).isEqualTo(snapshot);
					assertThat(logical.getServiceExpressionString()).isEqualTo(source);
					assertThat(logical.getPreparedInputBindings().get("x")).isSameAs(parameter);
					assertThat(actual).as("direct adapter=%s input rows=%s", sparql, count).hasSize(count);
					assertThat(actual).allSatisfy(row -> {
						assertThat(row.getBindingNames()).containsExactly("copy");
						assertThat(row.getValue("copy")).isSameAs(parameter);
					});
				}));
			}
		}));
	}

	@Test
	void directCanonicalAskExecutesTheTrustedIdentityThroughBothAdapters() {
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			try (Harness harness = new Harness(sparql)) {
				Value alias = harness.service("SELECT ?node WHERE {<urn:a> <urn:node> ?node}", Map.of())
						.get(0)
						.getValue("node");
				assertThat(alias).isInstanceOf(RemoteBNode.class);
				Service logical = preparedService("<urn:a> <urn:node> ?node", Map.of());
				Service snapshot = logical.clone();
				MapBindingSet input = new MapBindingSet();
				input.addBinding("node", alias);
				BNode unrelated = VF.createBNode("member");
				input.addBinding("local", unrelated);
				assertThat(harness.endpoint.ask(logical, input, null)).isTrue();
				assertThat(input.getBindingNames()).containsExactlyInAnyOrder("node", "local");
				assertThat(input.getValue("node")).isSameAs(alias);
				assertThat(input.getValue("local")).isSameAs(unrelated);

				Value absent = RemoteBNode.newResponseScope(new BlankNodeAllocationScope(), VF,
						harness.endpoint.getBNodeIdentityScope(), true).map(VF.createBNode("absent-canonical-node"));
				MapBindingSet missing = new MapBindingSet();
				missing.addBinding("node", absent);
				assertThat(harness.endpoint.ask(logical, missing, null)).isFalse();
				assertThat(missing.getValue("node")).isSameAs(absent);
				Value foreign = RemoteBNode.newResponseScope(new BlankNodeAllocationScope(), VF, new Object(), true)
						.map(VF.createBNode("member"));
				int requests = harness.requests.size();
				assertAll(List.<Value>of(unrelated, foreign).stream().map(unsupported -> () -> {
					MapBindingSet untrusted = new MapBindingSet();
					untrusted.addBinding("node", unsupported);
					assertThatThrownBy(() -> harness.endpoint.ask(logical, untrusted, null))
							.isInstanceOf(QueryEvaluationException.class)
							.hasMessageContaining("Unsupported blank-node identity");
					assertThat(untrusted.getValue("node")).isSameAs(unsupported);
					assertThat(harness.requests).hasSize(requests);
				}));
				harness.endpoint.setCanonicalBNodeIDsSupported(false);
				assertThatThrownBy(() -> harness.endpoint.ask(logical, input, null))
						.isInstanceOf(QueryEvaluationException.class)
						.hasMessageContaining("Unsupported blank-node identity");
				assertThat(harness.requests).hasSize(requests);
				assertThat(input.getValue("node")).isSameAs(alias);
				assertThat(input.getValue("local")).isSameAs(unrelated);
				assertThat(logical).isEqualTo(snapshot);
			}
		}));
	}

