	@Test
	void directPreparedServiceKeepsNullableOuterInputBranches() {
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			try (Harness harness = new Harness(sparql)) {
				Map<String, Value> parameters = Map.of("x", VF.createIRI("urn:a"));
				// A fixed value from only one possible branch cannot justify discarding an outer mapping.
				for (String body : List.of("OPTIONAL {?x <urn:p> ?o}",
						"{?x <urn:p> ?o} UNION {BIND(\"independent\" AS ?keep)}")) {
					Service nullable = preparedService(body, parameters);
					MapBindingSet input = new MapBindingSet();
					input.addBinding("x", VF.createIRI("urn:b"));
					List<BindingSet> actual = new ArrayList<>();
					try (var rows = harness.endpoint.evaluate(nullable,
							new CloseableIteratorIteration<>(List.<BindingSet>of(input).iterator()), null)) {
						while (rows.hasNext()) {
							actual.add(rows.next());
						}
					}
					MapBindingSet expected = new MapBindingSet();
					expected.addBinding("x", VF.createIRI("urn:b"));
					if (body.contains("UNION")) {
						expected.addBinding("keep", VF.createLiteral("independent"));
					}
					assertThat(actual).as("nullable adapter=%s body=%s", sparql, body).containsExactly(expected);
				}
			}
		}));
	}

	private static Service preparedService(String body, Map<String, Value> parameters) {
		return preparedService(body, parameters, false);
	}

	private static Service preparedService(String body, Map<String, Value> parameters, boolean silent) {
		TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT * WHERE {SERVICE " + (silent ? "SILENT " : "") + "<urn:endpoint> {" + body + "}}", null)
				.getTupleExpr();
		MapBindingSet inputs = new MapBindingSet();
		parameters.forEach(inputs::addBinding);
		new BindingAssignerOptimizer().optimizeForPreparedQuery(expression, inputs);
		AtomicReference<Service> found = new AtomicReference<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Service service) {
				found.set(service);
			}
		});
		assertThat(found.get().getPreparedInputBindings()).containsAllEntriesOf(parameters);
		return found.get();
	}

