	@Test
	void lexicalConstantPredicateRuntimeTransportExecutesSourceAndPreservesCallerDomain() {
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			try (Harness harness = new Harness(sparql)) {
				var predicate = VF.createIRI("urn:test:p");
				try (var connection = harness.data.getConnection()) {
					connection.add(VF.createBNode("member"), predicate, VF.createLiteral("remote"));
					connection.add(VF.createBNode("member"), VF.createIRI("urn:wrong:p"),
							VF.createLiteral("wrong predicate"));
					connection.add(VF.createBNode("other"), predicate, VF.createLiteral("wrong subject"));
				}
				Value alias = harness.service("SELECT ?node WHERE {<urn:a> <urn:node> ?node}", Map.of())
						.get(0)
						.getValue("node");
				Service service = new Service(Var.of("endpoint", VF.createIRI("urn:endpoint"), true, true),
						new StatementPattern(Var.of("s"), Var.of("p", predicate), Var.of("o")), "?s ?p ?o", Map.of(),
						null, false);
				MapBindingSet input = new MapBindingSet();
				input.addBinding("s", alias);
				input.addBinding("p", predicate);
				input.addBinding("endpoint", VF.createIRI("urn:caller:endpoint"));
				List<BindingSet> actual = new ArrayList<>();
				try (var rows = harness.endpoint.select(service, service.getServiceVars(), input, null)) {
					while (rows.hasNext()) {
						actual.add(rows.next());
					}
				}
				MapBindingSet expected = new MapBindingSet();
				input.forEach(expected::addBinding);
				expected.addBinding("o", VF.createLiteral("remote"));
				assertThat(actual).containsExactly(expected);
				assertThat(actual.get(0).getBindingNames()).containsExactlyInAnyOrder("s", "p", "endpoint", "o");
				assertThat(actual.get(0).getValue("s")).isSameAs(alias);
				assertThat(input.getBindingNames()).containsExactlyInAnyOrder("s", "p", "endpoint");
			}
		}));
	}

