	@Test
	void nestedServiceExpressionsAndSelectorsPreserveTheirOwnGrammarContexts() {
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			try (Harness outer = new Harness(sparql); Harness inner = new Harness(sparql)) {
				List<String> selectedEndpoints = new ArrayList<>();
				outer.data.setFederatedServiceResolver(selector -> {
					selectedEndpoints.add(selector);
					return inner.endpoint;
				});
				MapBindingSet first = new MapBindingSet();
				first.addBinding("item", VF.createLiteral("1", XSD.INTEGER));
				MapBindingSet second = new MapBindingSet();
				second.addBinding("item", VF.createLiteral("2", XSD.INTEGER));
				List<BindingSet> expected = List.of(first, second);
				assertAll(List.<Value>of(VF.createLiteral("key"), VF.createLiteral(3), VF.createIRI("urn:key"))
						.stream()
						.map(value -> () -> {
							assertAll(List.of("?sort", "(?sort)", "ASC(?sort)", "DESC(?sort)", "BOUND(?sort)",
									"ASC(BOUND(?sort))", "DESC(BOUND(?sort))").stream().map(order -> () -> {
										assertAll(List.of(false, true).stream().map(parameterSelector -> () -> {
											Map<String, Value> parameters = parameterSelector
													? Map.of("sort", value, "inner", VF.createIRI("urn:inner"))
													: Map.of("sort", value);
											String local = "SELECT ?item WHERE {VALUES ?item {1 2}} ORDER BY " + order;
											assertThat(Harness.evaluate(outer.data, local, parameters))
													.as("local nested grammar oracle order=%s sort=%s", order, value)
													.containsExactlyInAnyOrderElementsOf(expected);
											String selector = parameterSelector ? "?inner" : "<urn:inner>";
											String source = "SELECT ?item WHERE {SERVICE <urn:outer> {SERVICE "
													+ selector
													+ " {{" + local + "}}}}";
											try (var connection = outer.sender.getConnection()) {
												SailTupleQuery query = (SailTupleQuery) connection
														.prepareTupleQuery(source);
												parameters.forEach(query::setBinding);
												TupleExpr logical = query.getParsedQuery().getTupleExpr().clone();
												String saved = query.getParsedQuery().getSourceString();
												int calls = selectedEndpoints.size();
												int providerCalls = mockingDetails(inner.endpoint).getInvocations()
														.size();
												for (int attempt = 0; attempt < 2; attempt++) {
													assertThat(collect(query)).as("adapter=%s nested source=%s sort=%s",
															sparql, source, value)
															.containsExactlyInAnyOrderElementsOf(expected);
													assertThat(query.getParsedQuery().getTupleExpr())
															.isEqualTo(logical);
													assertThat(query.getParsedQuery().getSourceString())
															.isEqualTo(saved);
												}
												assertThat(selectedEndpoints.subList(calls, selectedEndpoints.size()))
														.isNotEmpty()
														.containsOnly("urn:inner");
												List<Service> invoked = mockingDetails(inner.endpoint).getInvocations()
														.stream()
														.skip(providerCalls)
														.filter(call -> Set.of("select", "ask", "evaluate")
																.contains(call.getMethod().getName()))
														.map(call -> call.<Service>getArgument(0))
														.toList();
												assertThat(invoked).isNotEmpty().allSatisfy(request -> {
													assertThat(request.getServiceRef().getValue())
															.isEqualTo(VF.createIRI("urn:inner"));
													assertThat(QueryParserUtil.parseBooleanQuery(QueryLanguage.SPARQL,
															request.getAskQueryString(), null).getTupleExpr())
																	.isNotNull();
												});
											}
										}));
									}));
						}));
			}
		}));
	}

	@Test
	void extractedNestedServiceBodiesKeepSourceAndAlgebraThroughCloneAndRepeatedPreparation() {
		Service logical = preparedService("SERVICE <urn:inner> {{SELECT ?item WHERE {VALUES ?item {1 2}} "
				+ "ORDER BY ASC(?sort)}}", Map.of("sort", VF.createLiteral("key")));
		Service snapshot = logical.clone();
		String saved = logical.getAskQueryString();
		assertAll(List.of(logical, logical.clone()).stream().map(candidate -> () -> {
			for (int attempt = 0; attempt < 2; attempt++) {
				Service request = SPARQLQueries.prepareServiceRequest(candidate, List.of(), null, false, false)
						.service();
				assertThat(request.getServiceExpressionString()).startsWith("SERVICE <urn:inner>");
				assertNestedInnerService(request.getServiceExpr());
				assertNestedInnerService(QueryParserUtil.parseBooleanQuery(QueryLanguage.SPARQL,
						request.getAskQueryString(), null).getTupleExpr());
				Service reused = SPARQLQueries.prepareServiceRequest(request.clone(), List.of(), null, false, false)
						.service();
				assertThat(reused.getAskQueryString()).isEqualTo(request.getAskQueryString());
				assertNestedInnerService(reused.getServiceExpr());
				assertThat(logical).isEqualTo(snapshot);
				assertThat(logical.getAskQueryString()).isEqualTo(saved);
			}
		}));
	}

	private static void assertNestedInnerService(TupleExpr expression) {
		List<Service> services = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Service service) {
				services.add(service);
				super.meet(service);
			}
		});
		assertThat(services).singleElement()
				.satisfies(
						service -> assertThat(service.getServiceRef().getValue()).isEqualTo(VF.createIRI("urn:inner")));
	}

	@Test
	void capturedGraphSelectorsUseCompatibilityRatherThanStatementOutputOverwrite() {
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			try (Harness harness = new Harness(sparql)) {
				MapBindingSet match = new MapBindingSet();
				match.addBinding("g", VF.createIRI("urn:graph"));
				match.addBinding("s", VF.createIRI("urn:a"));
				match.addBinding("o", VF.createLiteral("graph"));
				List<BasicGraphPatternCase> cases = List.of(
						new BasicGraphPatternCase("<urn:graph>", List.of(match)),
						new BasicGraphPatternCase("<urn:other>", List.of()),
						new BasicGraphPatternCase("<urn:graph> <urn:other> <urn:graph>", List.of(match, match)),
						new BasicGraphPatternCase("UNDEF", List.of(match)),
						new BasicGraphPatternCase("<urn:graph> UNDEF", List.of(match, match)));
				assertAll(cases.stream().map(test -> () -> {
					for (boolean before : List.of(true, false)) {
						String values = "VALUES ?g {" + test.body() + "}";
						String graph = "GRAPH ?g {?s <urn:p> ?o}";
						String body = before ? values + " " + graph : graph + " " + values;
						String query = "SELECT ?g ?s ?o WHERE {" + body + "}";
						Map<String, Value> parameters = Map.of("g", VF.createIRI("urn:graph"));
						assertThat(Harness.evaluate(harness.data, query, parameters)).as("local GRAPH query=%s", query)
								.containsExactlyInAnyOrderElementsOf(test.expected());
						assertThat(harness.service(query, parameters)).as("adapter=%s GRAPH query=%s", sparql, query)
								.containsExactlyInAnyOrderElementsOf(test.expected());
					}
				}));
			}
		}));
	}

	@Test
	void capturedGraphSelectorsPreserveSameNamedBodyScopes() {
		var graph = VF.createIRI("urn:graph");
		var other = VF.createIRI("urn:other");
		Map<String, Value> parameters = Map.of("g", graph);
		MapBindingSet match = new MapBindingSet();
		match.addBinding("g", graph);
		List<BasicGraphPatternCase> cases = List.of(
				new BasicGraphPatternCase("VALUES ?g {<urn:graph>}", List.of(match)),
				new BasicGraphPatternCase("VALUES ?g {<urn:other>}", List.of()),
				new BasicGraphPatternCase("BIND(<urn:graph> AS ?g)", List.of(match)),
				new BasicGraphPatternCase("BIND(<urn:other> AS ?g)", List.of()),
				new BasicGraphPatternCase("VALUES ?g {<urn:graph> <urn:other> <urn:graph> UNDEF}",
						List.of(match, match, match)),
				new BasicGraphPatternCase("{SELECT ?g WHERE {VALUES ?g {<urn:graph> <urn:other>}}}", List.of(match)),
				new BasicGraphPatternCase("?s <urn:p> ?o FILTER(sameTerm(?g, <urn:graph>))", List.of(match)),
				new BasicGraphPatternCase("BIND(?g AS ?copy) FILTER(sameTerm(?copy, <urn:graph>))", List.of(match)),
				new BasicGraphPatternCase("{SELECT ?copy WHERE {BIND(<urn:other> AS ?g) BIND(?g AS ?copy)}} "
						+ "FILTER(sameTerm(?copy, <urn:other>))", List.of(match)),
				new BasicGraphPatternCase("GRAPH ?g {VALUES ?g {<urn:graph>}}", List.of(match)),
				new BasicGraphPatternCase("GRAPH ?g {VALUES ?g {<urn:graph>}}GRAPH ?g {VALUES ?g {UNDEF}}",
						List.of(match)));
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			try (Harness harness = new Harness(sparql)) {
				try (var connection = harness.data.getConnection()) {
					connection.add(VF.createIRI("urn:a"), VF.createIRI("urn:p"), VF.createLiteral("other"), other);
				}
				assertAll(cases.stream().map(test -> () -> {
					String query = "SELECT ?g WHERE { GRAPH ?g {" + test.body() + "} }";
					assertThat(Harness.evaluate(harness.data, query, parameters)).as("local GRAPH query=%s", query)
							.containsExactlyInAnyOrderElementsOf(test.expected());
					assertThat(harness.service(query, parameters)).as("adapter=%s GRAPH query=%s", sparql, query)
							.containsExactlyInAnyOrderElementsOf(test.expected());
				}));
			}
		}));
	}

